  // -------------------------------------------------------
  // Filtres & Tri
  // -------------------------------------------------------
  appliquerFiltres() {
    console.log("=== APPLICATION DES FILTRES ===");
    console.log("Cat\xE9gorie active:", this.categorieActive);
    let result = [...this.tousLesProduits];
    console.log("Produits avant filtrage:", result.length);
    if (this.searchQuery.trim()) {
      const q = this.searchQuery.toLowerCase();
      result = result.filter((p) => p.nom.toLowerCase().includes(q) || p.marque.toLowerCase().includes(q) || p.description.toLowerCase().includes(q));
    }
    if (this.filtrePromo)
      result = result.filter((p) => p.discount !== null);
    if (this.filtreLivraison)
      result = result.filter((p) => p.livraison);
    if (this.filtreNew)
      result = result.filter((p) => p.isNew);
    if (this.prixMin !== null)
      result = result.filter((p) => p.prixNouveau >= this.prixMin);
    if (this.prixMax !== null)
      result = result.filter((p) => p.prixNouveau <= this.prixMax);
    if (this.noteMin > 0)
      result = result.filter((p) => p.note >= this.noteMin);
    switch (this.triActif) {
      case "prix-asc":
        result.sort((a, b) => a.prixNouveau - b.prixNouveau);
        break;
      case "prix-desc":
        result.sort((a, b) => b.prixNouveau - a.prixNouveau);
        break;
      case "note":
        result.sort((a, b) => b.note - a.note);
        break;
      case "promo":
        result.sort((a, b) => (b.discount ?? 0) - (a.discount ?? 0));
        break;
    }
    this.produitsFiltres = result;
    console.log("Produits apr\xE8s tous les filtres:", result.length);
  }
  resetFiltres() {
    this.searchQuery = "";
    this.filtrePromo = false;
    this.filtreLivraison = false;
    this.filtreNew = false;
    this.prixMin = null;
    this.prixMax = null;
    this.noteMin = 0;
    this.categorieActive = "tous";
    this.triActif = "pertinence";
    this.appliquerFiltres();
  }
  // -------------------------------------------------------
  // UI
  // -------------------------------------------------------
  toggleFilters() {
    this.showFilters = !this.showFilters;
  }
  setGrid() {
    this.viewMode = "grid";
  }
  setList() {
    this.viewMode = "list";
  }
  setCategorieActive(key) {
    this.categorieActive = key;
    console.log("Cat\xE9gorie active chang\xE9e:", key);
    this.loadProduits();
  }
  toggleFavori(produit, event) {
    event.stopPropagation();
    if (produit.isFavori) {
      this.monCompteService.retirerFavori(produit.id).subscribe({
        next: () => {
          produit.isFavori = false;
          this.notificationService.info(`${produit.nom} retir\xE9 des favoris`, "Favoris");
        },
        error: (err) => {
          console.error("Erreur lors du retrait des favoris:", err);
          this.notificationService.error("Erreur lors du retrait des favoris", "Erreur");
        }
      });
    } else {
      this.monCompteService.ajouterFavori(produit.id).subscribe({
        next: () => {
          produit.isFavori = true;
          this.notificationService.success(`${produit.nom} ajout\xE9 aux favoris`, "Favoris");
        },
        error: (err) => {
          console.error("Erreur lors de l'ajout aux favoris:", err);
          this.notificationService.error("Erreur lors de l'ajout aux favoris", "Erreur");
        }
      });
    }
  }
  goToProduit(id) {
    this.router.navigate(["/produits"], { queryParams: { id } });
  }
  // -------------------------------------------------------
  // Panier
  // -------------------------------------------------------
  ajouterAuPanier(produit, event) {
    event.stopPropagation();
    if (produit.stock === 0) {
      this.notificationService.warning("Ce produit est en rupture de stock", "Stock indisponible");
      return;
    }
    this.panierService.ajouterAuPanier({
      produit: {
        id: produit.id,
        nom: produit.nom,
        prix: produit.prixNouveau,
        image: produit.image ?? void 0,
        description: produit.description,
        stock: produit.stock,
        categorie: 0,
        gestionnaire_stock: 0
      },
      nom: produit.nom,
      prix: produit.prixNouveau,
      quantite: 1,
      image: produit.image ?? void 0
    });
    this.notificationService.success(`${produit.nom} a \xE9t\xE9 ajout\xE9 au panier`, "Produit ajout\xE9");
    this.produitAjoute = produit.id;
    setTimeout(() => {
      if (this.produitAjoute === produit.id)
        this.produitAjoute = null;
    }, 1500);
  }
  // -------------------------------------------------------
  // Helpers
  // -------------------------------------------------------
  getEtoiles() {
    return [1, 2, 3, 4, 5];
  }
  isPleine(i, note) {
    return i <= Math.floor(note);
  }
  isDemi(i, note) {
    return i === Math.ceil(note) && note % 1 >= 0.5;
  }
  isStockFaible(p) {
    return p.stock > 0 && p.stock <= 5;
  }
  getNbFiltresActifs() {
    let n = 0;
    if (this.filtrePromo)
      n++;
    if (this.filtreLivraison)
      n++;
    if (this.filtreNew)
      n++;
    if (this.prixMin !== null)
      n++;
    if (this.prixMax !== null)
      n++;
    if (this.noteMin > 0)
      n++;
    if (this.categorieActive !== "tous")
      n++;
    return n;
  }
