  // ACTIONS FAVORIS
  // -------------------------------------------------------
  ajouterAuPanierDepuisFavori(favori) {
    this.panierService.ajouterProduit({
      id: favori.produit_id,
      nom: favori.produit_nom,
      prix: favori.prix,
      quantite: 1
    });
    this.notificationService.success(`${favori.produit_nom} a \xE9t\xE9 ajout\xE9 au panier`, "Ajout\xE9 au panier");
    this.refreshPanier();
  }
  retirerDesFavoris(favori) {
    this.monCompteService.retirerFavori(favori.produit_id).subscribe({
      next: () => {
        this.notificationService.warning(`${favori.produit_nom} a \xE9t\xE9 retir\xE9 des favoris`, "Favori supprim\xE9");
        this.refreshFavoris();
      },
      error: () => {
        this.notificationService.error("Impossible de retirer des favoris", "Erreur");
      }
    });
  }
  // -------------------------------------------------------
  // ACTIONS PANIER
  // -------------------------------------------------------
  supprimerDuPanier(item) {
    this.monCompteService.supprimerDuPanier(item.id).subscribe({
      next: () => {
        this.notificationService.warning(`${item.produit_nom} a \xE9t\xE9 retir\xE9 du panier`, "Produit supprim\xE9");
        this.refreshPanier();
      },
      error: () => {
        this.notificationService.error("Impossible de supprimer du panier", "Erreur");
      }
    });
  }
  mettreAJourQuantite(item, nouvelleQuantite) {
    if (nouvelleQuantite < 1)
      return;
    this.monCompteService.mettreAJourQuantite(item.id, nouvelleQuantite).subscribe({
      next: () => {
        this.refreshPanier();
      },
      error: () => {
        this.notificationService.error("Impossible de mettre \xE0 jour la quantit\xE9", "Erreur");
      }
    });
  }
  passerCommande() {
    this.notificationService.info("La fonctionnalit\xE9 de commande sera bient\xF4t disponible", "Information");
  }
